const now = Date.now();
const norm = (u) => { const m = String(u || '').trim().match(/^https?:\/\/(?:www\.)?([^\/?#]+)([^?#]*)(?:\?[^#]*)?(#\S*)?/i); return m ? (m[1] + m[2].replace(/\/+$/, '') + (m[3] || '')).toLowerCase() : null; };
const hostOf = (u) => { const m = String(u || '').match(/^https?:\/\/(?:www\.)?([^\/?#]+)/i); return m ? m[1].toLowerCase() : ''; };
const hist = $('Get history').all().map(i => i.json);
const seen = new Set(hist.flatMap(r => String(r.urls || '').split(' ')).filter(Boolean));
const names = { 'agrotimes.ua': 'AgroTimes', 'superagronom.com': 'SuperAgronom', 'latifundist.com': 'Latifundist' };
const WINDOW_HOURS = 24;
const items = $('Merge feeds').all().map(i => i.json).sort((a, b) => (Date.parse(b.isoDate || b.pubDate || '') || 0) - (Date.parse(a.isoDate || a.pubDate || '') || 0));
const out = [];
for (const j of items) {
  const u = norm(j.link);
  const t = Date.parse(j.isoDate || j.pubDate || '');
  if (!u || !j.title || seen.has(u)) continue;
  if (!t || now - t > WINDOW_HOURS * 3600 * 1000) continue;
  seen.add(u);
  const host = hostOf(j.link);
  out.push({ id: 'c' + (out.length + 1), title: j.title, summary: String(j['content:encodedSnippet'] || j.contentSnippet || '').replace(/\s+/g, ' ').slice(0, 1200), published_at: new Date(t).toISOString(), source_name: names[host] || host, url: j.link });
}
return [{ json: { candidates: out.slice(0, 25) } }];

const cands = $('Prepare candidates').first().json.candidates;
const byId = Object.fromEntries(cands.map(c => [c.id, c]));
const norm = (u) => { const m = String(u || '').trim().match(/^https?:\/\/(?:www\.)?([^\/?#]+)([^?#]*)(?:\?[^#]*)?(#\S*)?/i); return m ? (m[1] + m[2].replace(/\/+$/, '') + (m[3] || '')).toLowerCase() : null; };
const repair = (s) => {
  let t = String(s).replace(/```(?:json)?/gi, '').trim();
  const a = t.indexOf('{'); if (a < 0) return null; t = t.slice(a);
  try { return JSON.parse(t); } catch (e) {}
  const stack = []; let inStr = false, escp = false;
  for (const ch of t) {
    if (inStr) { if (escp) escp = false; else if (ch === '\\') escp = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') inStr = true;
    else if (ch === '{' || ch === '[') stack.push(ch);
    else if (ch === '}' || ch === ']') stack.pop();
  }
  let fixed = t + (inStr ? '"' : '');
  for (let i = stack.length - 1; i >= 0; i--) fixed += stack[i] === '{' ? '}' : ']';
  try { return JSON.parse(fixed); } catch (e) {}
  const cut = fixed.replace(/,[^,{\[]*$/, '');
  try { return JSON.parse(cut); } catch (e) {}
  return null;
};
const lift = (post) => {
  if (!post || !Array.isArray(post.blocks)) return post;
  for (const b of post.blocks) {
    if (!b || typeof b !== 'object') continue;
    for (const k of ['closing_line', 'hashtags', 'image_prompt', 'headline', 'post_type']) {
      if (k in b && (post[k] === undefined || post[k] === null || post[k] === '')) post[k] = b[k];
    }
  }
  return post;
};
const pairs = (raw) => {
  const out = [], seen = new Set();
  const re = /"news_id"\s*:\s*"([^"]+)"\s*,\s*"text"\s*:\s*"((?:[^"\\]|\\.)*)"|"text"\s*:\s*"((?:[^"\\]|\\.)*)"\s*,\s*"news_id"\s*:\s*"([^"]+)"/g;
  let m;
  while ((m = re.exec(String(raw))) !== null) {
    const id = m[1] || m[4];
    const txt = m[2] !== undefined ? m[2] : m[3];
    if (!id || txt === undefined || seen.has(id)) continue;
    seen.add(id);
    try { out.push({ news_id: id, text: JSON.parse('"' + txt + '"') }); } catch (e) {}
  }
  return out;
};
const rawText = (() => {
  const j = $input.first().json;
  if (typeof j.content === 'string') return j.content;
  const st = [j];
  while (st.length) {
    const v = st.pop();
    if (typeof v === 'string' && v.includes('news_id')) return v;
    if (v && typeof v === 'object') st.push(...Object.values(v));
  }
  return '';
})();
const find = (root, key) => {
  const st = [root];
  while (st.length) {
    const v = st.pop();
    if (v && typeof v === 'object') { if (!Array.isArray(v) && key in v) return v; st.push(...Object.values(v)); }
    else if (typeof v === 'string' && v.includes(key)) { const p = repair(v); if (p && key in p) return p; }
  }
  return null;
};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const attr = s => esc(s).replace(/"/g, '&quot;');
let post = find($input.first().json, 'blocks');
post = lift(post);
if (post) {
  const parsedBlocks = Array.isArray(post.blocks) ? post.blocks.filter(b => b && b.text) : [];
  const extracted = pairs(rawText);
  if (extracted.length > parsedBlocks.length) post.blocks = extracted;
}
if (!post) return [{ json: { skip: true, reason: 'модель повернула некоректну відповідь' } }];
if (post.status !== 'ok' || !Array.isArray(post.blocks)) return [{ json: { skip: true, reason: post.skip_reason || 'нічого важливого' } }];
const blocks = post.blocks.filter(b => b && b.text && byId[b.news_id]);
if (!blocks.length || !post.headline) return [{ json: { skip: true, reason: 'порожній текст від моделі' } }];
const last = {};
blocks.forEach((b, i) => { last[b.news_id] = i; });
const bullet = post.post_type === 'digest' ? '• ' : '';
const html = ['<b>' + esc(post.headline) + '</b>'];
const plain = [String(post.headline)];
blocks.forEach((b, i) => {
  let h = bullet + esc(b.text);
  let p = bullet + b.text;
  if (last[b.news_id] === i) {
    const c = byId[b.news_id];
    h += '\nДжерело: <a href="' + attr(c.url) + '">' + esc(c.source_name) + '</a>';
    p += '\nДжерело: ' + c.source_name;
  }
  html.push(h); plain.push(p);
});
if (post.closing_line) { html.push(esc(post.closing_line)); plain.push(post.closing_line); }
const tags = (post.hashtags || []).slice(0, 3).join(' ');
if (tags) { html.push(esc(tags)); plain.push(tags); }
const used = [...new Set(blocks.map(b => b.news_id))];
const image_prompt = String(post.image_prompt || '').trim();
return [{ json: {
  skip: false,
  draft_id: Date.now().toString(36),
  final_html: html.join('\n\n'),
  image_prompt,
  with_image: image_prompt.length > 30 && plain.join('\n\n').length <= 1024,
  urls: used.map(id => norm(byId[id].url)).filter(Boolean).join(' '),
  titles: used.map(id => byId[id].title).join(' | ')
} }];

const res = ($input.first().json.results || []).filter(r => r.url && /\.(jpe?g|png)(\?|$)/i.test(r.url) && (!r.width || r.width >= 800));
const r = res[Math.floor(Math.random() * Math.min(res.length, 5))];
if (!r) return [{ json: { url: 'invalid://none', credit: '' } }];
const lic = String(r.license || '').toUpperCase();
const credit = '📷 ' + String(r.creator || 'unknown').replace(/[<>&]/g, '') + ' / ' + (r.source || 'Openverse') + ', CC ' + lic;
return [{ json: { url: r.url, credit } }];

