const resp = $input.first().json;
const b64 = (resp.images && resp.images[0]) || null;
if (!b64) throw new Error('Draw Things returned no image: ' + JSON.stringify(resp).slice(0, 200));
const buf = Buffer.from(String(b64).replace(/^data:image\/\w+;base64,/, ''), 'base64');
if (buf.length < 2000) throw new Error('Generated image too small: ' + buf.length + ' bytes');
const bin = await this.helpers.prepareBinaryData(buf, 'ai-image.png', 'image/png');
return [{ json: { generated: true, bytes: buf.length }, binary: { data: bin } }];
